<?php
$wali=isset($_GET['wali'])?ak_one('SELECT * FROM ak_wali_kelas WHERE id=? AND id_tahun_ajaran=?',[input_id($_GET,'wali'),$periodId]):null;
?><details class="panel" <?=$wali?'open':''?>><summary>Penugasan Wali Kelas</summary><p><?=app_setting('HOMEROOM_MODE')==='informational'?'Wali merupakan informasi penanggung jawab kelas. Tugas mengajar/absensi/jurnal ditentukan penugasan guru mapel; verifikasi rapor dilakukan Admin.':'Wali memeriksa draft kelas/periode/tanggal tugasnya. Tidak memperoleh hak Admin atau mengubah nilai mapel lain.'?></p><form method="post"><?=csrf_field()?><?php ak_hidden('action','wali');ak_hidden('id_tahun_ajaran',$periodId);if($wali)ak_hidden('id',$wali['id']);?><div class="form-grid"><?php ak_select('id_guru','Guru wali',$teachers,$wali['id_guru']??'');ak_select('id_kelas','Kelas',$classes,$wali['id_kelas']??'');ak_field('mulai','Berlaku mulai',$wali['mulai']??'','date');ak_field('selesai','Berlaku sampai',$wali['selesai']??'','date');?></div><?php ak_field('catatan','Dasar penugasan / pencabutan',$wali['catatan']??'');?><button type="submit">Simpan tugas wali</button><?php if($wali):?><button type="submit" class="secondary" name="operation" value="cabut">Cabut tugas wali</button><?php endif;?></form></details>
<section class="panel"><h2>Daftar Wali Kelas</h2><?php foreach(ak_rows('SELECT w.*,g.nama_guru,k.nama_kelas FROM ak_wali_kelas w JOIN guru g USING(id_guru) JOIN kelas k USING(id_kelas) WHERE w.id_tahun_ajaran=? ORDER BY w.id DESC',[$periodId]) as $row):?><article class="history-entry"><strong><?=e($row['nama_guru'])?> · <?=e($row['nama_kelas'])?></strong><p><?=e($row['mulai'])?> — <?=e($row['selesai'])?> · <?=$row['aktif']?'Aktif':'Dicabut'?></p><a class="button secondary" href="<?=e(ak_link('fondasi',['id_tahun_ajaran'=>$periodId,'wali'=>$row['id']]))?>">Edit / cabut wali</a></article><?php endforeach;?></section>
